    val n = br.readLine().toInt()
    if (n == 1) {
        println(1)
        return
    }
    val adj = Array(n + 1) { mutableListOf<Int>() }
    repeat(n - 1) {
        val (u, v) = br.readLine().split(" ").map { it.toInt() }
        adj[u].add(v)
        adj[v].add(u)
    }

    // Root the tree at 1
    val parent = Array(n + 1) { 0 }
    val children = Array(n + 1) { mutableListOf<Int>() }
    val visited = BooleanArray(n + 1)
    val q = ArrayDeque<Int>()
    q.add(1)
    visited[1] = true
    while (q.isNotEmpty()) {
        val u = q.poll()
        for (v in adj[u]) {
            if (!visited[v]) {
                visited[v] = true
                parent[v] = u
                children[u].add(v)
                q.add(v)
            }
        }
    }

    // Post-order traversal
    val postOrder = mutableListOf<Int>()
    val stack = Stack<Pair<Int, Boolean>>()
    stack.push(Pair(1, false))
    while (stack.isNotEmpty()) {
        val (u, processed) = stack.pop()
        if (processed) {
            postOrder.add(u)
            continue
        }
        stack.push(Pair(u, true))
        for (v in children[u]) {
            stack.push(Pair(v, false))
        }
    }

    val dp0 = LongArray(n + 1) // dp0[u]: number of ways when u is not matched to any child
    val dp1 = LongArray(n + 1) // dp1[u]: number of ways when u is matched to one child
    val matched = BooleanArray(n + 1) // whether the maximum matching is unique

    for (u in postOrder) {
        if (children[u].isEmpty()) {
            dp0[u] = 1
            dp1[u] = 0
            matched[u] = true
            continue
        }
        var prod0 = 1L
        var prod1 = 0L
        var hasUnique = true
        for (v in children[u]) {
            val newProd0 = (prod0 * (dp0[v] + dp1[v])) % MOD
            val newProd1 = (prod1 * (dp0[v] + dp1[v]) + prod0 * dp0[v]) % MOD
            prod0 = newProd0
            prod1 = newProd1
            if (!matched[v]) {
                hasUnique = false
            }
        }
        dp0[u] = prod0
        dp1[u] = prod1
        matched[u] = hasUnique
    }

    var ans = 0L
    if (matched[1]) {
        ans = (dp0[1] + dp1[1]) % MOD
    } else {
        ans = 0
    }
    println(ans)
}
