fun modInverse(a: Long, mod: Int): Long {
    var a = a % mod
    var m = mod.toLong()
    var y = 0L
    var x = 1L
    while (m > 0L) {
        val q = a / m
        val temp = y
        y = x - q * y
        x = temp
        val temp2 = a % m
        a = m
        m = temp2
    }
    if (a != 1L) {
        throw ArithmeticException("Modular inverse does not exist")
    }
    return (x % mod + mod) % mod
}
